-- ex_07_b.sql
-- Exercise 07 - b
-- Farms in 54518 between 1600 and 1800 masl, by rural district ASC then area DESC
SELECT
    T1.farm_id, T1.farmer_id, T1.municipality_code, T1.farm_name,
    T1.rural_district, T1.total_area_ha, T1.altitude_masl,
    T1.latitude, T1.longitude, T1.registered_at
FROM farm.farms AS T1
WHERE T1.municipality_code = '54518'
  AND T1.altitude_masl BETWEEN 1600 AND 1800
ORDER BY T1.rural_district ASC, T1.total_area_ha DESC;


